// Serializes the refunds and the reversal of one collection.
func (q *Queries) LockLedgerEntry(ctx context.Context, arg LockLedgerEntryParams) (int64, error) {
	row := q.db.QueryRow(ctx, lockLedgerEntry, arg.OrganizationID, arg.ID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const refundedOfCollection = `-- name: RefundedOfCollection :one
SELECT COALESCE(SUM(f.amount) FILTER (
    WHERE NOT EXISTS (SELECT 1 FROM ledger_entries r WHERE r.organization_id = f.organization_id AND r.reverses_entry_id = f.id)
), 0)::numeric AS refunded
FROM ledger_entries f
WHERE f.organization_id = $1 AND f.refunds_entry_id = $2 AND f.kind = 'refund'
`

type RefundedOfCollectionParams struct {
	OrganizationID int64       `json:"organization_id"`
	CollectionID   pgtype.Int8 `json:"collection_id"`
}

// Amount paid back from one collection (refunds minus reversed refunds).
func (q *Queries) RefundedOfCollection(ctx context.Context, arg RefundedOfCollectionParams) (pgtype.Numeric, error) {
	row := q.db.QueryRow(ctx, refundedOfCollection, arg.OrganizationID, arg.CollectionID)
	var refunded pgtype.Numeric
	err := row.Scan(&refunded)
	return refunded, err
}

const salesCashByDay = `-- name: SalesCashByDay :many
SELECT m.movement_date, m.currency::text AS currency,
    COALESCE(SUM(CASE WHEN m.kind = 'transfer_out' THEN m.amount
                      WHEN m.kind = 'reversal' AND o.kind = 'transfer_out' THEN -m.amount END), 0)::numeric AS transfers,
    COALESCE(SUM(CASE WHEN m.kind = 'staff_payment' THEN m.amount
                      WHEN m.kind = 'reversal' AND o.kind = 'staff_payment' THEN -m.amount END), 0)::numeric AS staff_payments
FROM cash_movements m
LEFT JOIN cash_movements o ON o.organization_id = m.organization_id AND o.id = m.reverses_movement_id
WHERE m.organization_id = $1
  AND m.movement_date BETWEEN $2::date AND $3::date
  AND (m.kind IN ('transfer_out', 'staff_payment') OR o.kind IN ('transfer_out', 'staff_payment'))
  AND ($4::bigint[] IS NULL OR m.branch_id = ANY($4::bigint[]))
  AND ($5::bigint[] IS NULL OR m.branch_id = ANY($5::bigint[]))
GROUP BY m.movement_date, m.currency
ORDER BY m.movement_date, m.currency
`

type SalesCashByDayParams struct {
	OrganizationID  int64       `json:"organization_id"`
	DateFrom        pgtype.Date `json:"date_from"`
	DateTo          pgtype.Date `json:"date_to"`
	BranchIds       []int64     `json:"branch_ids"`
	FilterBranchIds []int64     `json:"filter_branch_ids"`
}

type SalesCashByDayRow struct {
	MovementDate  pgtype.Date    `json:"movement_date"`
	Currency      string         `json:"currency"`
	Transfers     pgtype.Numeric `json:"transfers"`
	StaffPayments pgtype.Numeric `json:"staff_payments"`
}

// Transfers between accounts and staff payouts per day and currency from
// the cash book (reversals netted); neither is revenue.
func (q *Queries) SalesCashByDay(ctx context.Context, arg SalesCashByDayParams) ([]SalesCashByDayRow, error) {
	rows, err := q.db.Query(ctx, salesCashByDay,
		arg.OrganizationID,
		arg.DateFrom,
		arg.DateTo,
		arg.BranchIds,
		arg.FilterBranchIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SalesCashByDayRow{}
	for rows.Next() {
		var i SalesCashByDayRow
		if err := rows.Scan(
			&i.MovementDate,
			&i.Currency,
			&i.Transfers,
			&i.StaffPayments,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const salesCollectionsByDay = `-- name: SalesCollectionsByDay :many
SELECT e.entry_date, e.currency::text AS currency,
    COALESCE(SUM(e.amount) FILTER (WHERE e.kind = 'collection'), 0)::numeric AS collected,
    COALESCE(SUM(e.amount) FILTER (WHERE e.kind = 'refund'), 0)::numeric AS refunded,
    COALESCE(SUM(CASE WHEN e.kind = 'reversal' AND o.kind = 'collection' THEN -e.amount
                      WHEN e.kind = 'reversal' AND o.kind = 'refund' THEN e.amount END), 0)::numeric AS reversed,
    COUNT(*) FILTER (WHERE e.kind = 'collection')::bigint AS collection_count
FROM ledger_entries e
LEFT JOIN ledger_entries o ON o.organization_id = e.organization_id AND o.id = e.reverses_entry_id
WHERE e.organization_id = $1
  AND e.entry_date BETWEEN $2::date AND $3::date
  AND (e.kind IN ('collection', 'refund') OR o.kind IN ('collection', 'refund'))
  AND ($4::bigint[] IS NULL OR e.branch_id = ANY($4::bigint[]))
  AND ($5::bigint[] IS NULL OR e.branch_id = ANY($5::bigint[]))
GROUP BY e.entry_date, e.currency
ORDER BY e.entry_date, e.currency
`

